import fs from "node:fs";
import {
  createPublicClient,
  createWalletClient,
  custom,
  defineChain,
  type Abi,
  type Account,
  type Address,
  type Chain,
  type Hex,
  type PublicClient,
  type Transport,
  type WalletClient,
} from "viem";
import { privateKeyToAccount } from "viem/accounts";
import type { LocalChain } from "./local-chain.js";

/** Shape of contracts/artifacts/BindSettlement.json (generated by tools/compile-contract/generate.mjs). */
export interface BindSettlementArtifact {
  contractName: string;
  solcVersion: string;
  evmVersion: string;
  sourceSha256: string;
  abi: Abi;
  bytecode: Hex;
}

const ARTIFACT_URL = new URL("../../contracts/artifacts/BindSettlement.json", import.meta.url);

export function loadArtifact(): BindSettlementArtifact {
  return JSON.parse(fs.readFileSync(ARTIFACT_URL, "utf8")) as BindSettlementArtifact;
}

export interface ViemClients {
  publicClient: PublicClient<Transport, Chain>;
  walletClient: WalletClient<Transport, Chain, Account>;
  account: Account;
}

/** viem public and wallet clients whose transport is the in-process chain. */
export function viemClients(chain: LocalChain, privateKey: Hex): ViemClients {
  const transport = custom({ request: chain.request as any });
  const chainDef = defineChain({
    id: chain.chainId,
    name: "local",
    nativeCurrency: { name: "USDC", symbol: "USDC", decimals: 18 },
    rpcUrls: { default: { http: [] } },
  });
  const account = privateKeyToAccount(privateKey);
  const publicClient = createPublicClient({ chain: chainDef, transport, pollingInterval: 5 });
  const walletClient = createWalletClient({ account, chain: chainDef, transport });
  return { publicClient, walletClient, account };
}

export async function deployBindSettlement(
  chain: LocalChain,
  privateKey: Hex
): Promise<ViemClients & { address: Address; abi: Abi }> {
  const artifact = loadArtifact();
  const { publicClient, walletClient, account } = viemClients(chain, privateKey);
  const hash = await walletClient.deployContract({
    abi: artifact.abi,
    bytecode: artifact.bytecode,
    gas: 5_000_000n,
  });
  const receipt = await publicClient.waitForTransactionReceipt({ hash });
  if (receipt.status !== "success" || !receipt.contractAddress) {
    throw new Error(`BindSettlement deployment failed (status ${receipt.status})`);
  }
  return { address: receipt.contractAddress, abi: artifact.abi, publicClient, walletClient, account };
}
